from pathlib import Path
import json
b=Path(__file__).resolve().parent.parent;chapters=json.loads((b/'Sources/Chapters.json').read_text());data=json.dumps(chapters,ensure_ascii=False)
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>World Map — Twenty Regions · Design R1</title><style>
@font-face{font-family:Body;src:url('Assets/Body.ttf')}@font-face{font-family:Numbers;src:url('Assets/Numbers.ttf')}
*{box-sizing:border-box}body{margin:0;background:#080e16;color:#e3c798;font:15px system-ui}main{max-width:650px;margin:0 auto;padding:18px 12px 32px}h1{font-size:23px;margin:8px 0}p{line-height:1.5}a{color:#9dc7e4}label{display:inline-flex;flex-direction:column;gap:5px;font-size:12px}select,.review-button{background:#142435;color:#ebd8b6;border:1px solid #886c3c;border-radius:5px;padding:9px;font:inherit}.tools{display:flex;flex-wrap:wrap;gap:9px;margin:14px 0}.note{font-size:12px;color:#aeacaa}#device{position:relative;width:100%;aspect-ratio:941/1672;overflow:hidden;box-shadow:0 12px 70px #0008;border:1px solid #5c492d;background:#0a141c}#stage{position:absolute;width:941px;height:1672px;transform-origin:top left;overflow:hidden;background:#0a151d;font-family:Body,serif;color:#f0dbab}button{font-family:inherit;cursor:pointer}button:focus-visible{outline:3px solid #d2efff;outline-offset:-4px}button:disabled{cursor:default}.header{position:absolute;inset:0 0 auto;height:140px;z-index:5;background:#0b1620}.art{position:absolute;object-fit:contain;pointer-events:none}.heroName,.heroLevel,.balance{position:absolute;z-index:1;text-shadow:0 2px 3px #000;margin:0}.heroName{left:180px;top:23px;font-size:34px}.heroLevel{left:180px;top:70px;font-size:24px}.balance{top:51px;font-family:Body;font-size:22px}.bar{position:absolute;left:194px;top:112px;width:126px;height:6px;background:linear-gradient(90deg,#338bc0 55%,#08101a 55%);border:1px solid #ab7e36}.title{left:190px;top:124px;width:561px;height:184px;z-index:4;filter:drop-shadow(0 8px 9px #000)}.title-backdrop{position:absolute;top:133px;width:100%;height:183px;background:radial-gradient(ellipse,#1b2c39,#080f18);z-index:3;border-bottom:1px solid #5f4a2c}.map-window{position:absolute;left:16px;right:16px;top:306px;height:1024px;overflow-y:auto;overflow-x:hidden;scrollbar-width:thin;scrollbar-color:#a58042 #0c1720;overscroll-behavior:contain;touch-action:pan-y;border-left:2px solid #796038;border-right:2px solid #796038;background:#101c23}.region{position:relative;display:block;width:100%;height:310px;border:0;padding:0;text-align:left;color:#f7dfa6;background:#101b21;overflow:hidden;isolation:isolate}.terrain{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-3}.shade{position:absolute;inset:0;background:linear-gradient(0deg,#07101cf2 0%,#08101a70 23%,transparent 65%,#08101a38);z-index:-2}.region.locked .terrain{filter:saturate(.5) brightness(.72)}.region.locked .shade{background:linear-gradient(0deg,#08121bf2,#08131f22 70%)}.region.active:after{content:'';position:absolute;inset:5px 6px;border:2px solid #e9b75499;box-shadow:inset 0 0 25px #bf8d242b;pointer-events:none}.number{position:absolute;left:32px;bottom:36px;width:78px;height:78px;display:grid;place-items:center;border-radius:50%;border:3px solid #c79842;background:radial-gradient(circle at 40% 30%,#244866,#071321 72%);box-shadow:0 3px 6px #000,inset 0 0 0 3px #271b0b,inset 0 0 0 5px #916c30;font:42px Numbers;color:#ead399}.active .number{box-shadow:0 0 22px #e7ac4688,inset 0 0 0 3px #563811}.locked .number{border-color:#766139;color:#c5b486;background:#13212c}.copy{position:absolute;left:130px;bottom:27px;right:110px}.chapter{font-size:23px;letter-spacing:2px;color:#dac08d}.name{display:block;font-size:37px;line-height:1.12;margin:3px 0 5px;text-shadow:0 2px 4px #000}.status{font-size:24px;color:#debe7d}.completed .status{color:#bcdbb3}.active .status{color:#f4d894}.locked .status{color:#b7c0c6}.lock{position:absolute;right:37px;bottom:49px;width:57px;height:72px;object-fit:contain;filter:drop-shadow(0 2px 3px #000)}.check{position:absolute;right:37px;bottom:55px;width:52px;height:52px;border-radius:50%;background:#153525dd;border:2px solid #c69b50;text-align:center;font-size:35px;color:#f5e0a6}.footer{position:absolute;left:0;bottom:0;width:941px;height:342px;z-index:4;background:linear-gradient(#08121caa,#050b12 32%);border-top:2px solid #b28b46;box-shadow:0 -9px 25px #04090ccc}.nav{position:absolute;top:8px;height:334px;background:none;border:0;padding:0}.nav img{width:100%;height:100%;object-fit:fill;pointer-events:none}.nav[data-nav=map]{left:0;width:342px}.nav[data-nav=tasks]{left:342px;width:263px}.nav[data-nav=guild]{left:605px;width:336px}.back{position:absolute;left:23px;top:204px;width:76px;height:76px;border:0;background:none;padding:0;z-index:6}.back img{width:100%;height:100%;object-fit:contain}.scrollHint{position:absolute;top:277px;right:25px;z-index:5;font-size:18px;color:#d1b681;pointer-events:none}.toast{position:absolute;left:105px;right:105px;top:565px;z-index:10;border:2px solid #c49b52;padding:32px;background:#091b2cf5;box-shadow:0 8px 60px #000;color:#f7d8a5;font-size:32px;text-align:center;display:none}.toast.visible{display:block}.toast button{margin-top:18px;padding:12px 34px;background:#113b32;border:1px solid #ae8b4c;color:#f4deac;font-size:28px}.compact .region{height:246px}.compact .name{font-size:34px}.compact .copy{bottom:20px}.compact .number{bottom:27px}.compact .lock{bottom:38px}.compact .check{bottom:40px}
</style></head><body><main><h1>World Map — Twenty Regions</h1><p>Design proposal using your chapter document and Scenario artwork. Swipe upward inside the map to reveal later chapters. This is an interactive browser preview, not a Unity implementation.</p><div class="tools"><label>Preview progress<select id="progress"><option value="1">Chapter 1 active</option><option value="3" selected>Chapters 1–2 complete · 3 active</option><option value="8">Chapters 1–7 complete · 8 active</option><option value="20">Chapters 1–19 complete · 20 active</option><option value="21">All chapters complete</option></select></label><label>Visible regions<select id="density"><option value="3">3 + next-region preview</option><option value="4">4 + next-region preview</option></select></label><button class="review-button" id="current">Jump to active</button><button class="review-button" id="start">Return to beginning</button></div>
<div id="device"><div id="stage"><div class="header"><img class="art" src="Assets/source_header.png" style="left:0;top:0;width:941px;height:140px"><img class="art" src="Assets/source_avatar.png" style="left:0;top:0;width:174px;height:235px"><p class="heroName">Иван</p><p class="heroLevel">Уровень 28</p><div class="bar"></div><img class="art" src="Assets/source_gold.png" style="left:344px;top:39px;width:180px;height:61px"><p class="balance" style="left:408px">12 540</p><img class="art" src="Assets/source_gems.png" style="left:529px;top:39px;width:165px;height:61px"><p class="balance" style="left:589px">350</p><img class="art" src="Assets/source_energy.png" style="left:702px;top:39px;width:149px;height:61px"><p class="balance" style="left:750px">25/30</p><img class="art" src="Assets/source_settings.png" style="left:853px;top:23px;width:88px;height:95px"></div><div class="title-backdrop"></div><img class="art title" src="Assets/title.png"><button class="back" aria-label="Back preview"><img src="Assets/back.png" alt="Back"></button><span class="scrollHint">20 глав · листайте вверх ↑</span><div class="map-window" id="map" aria-label="Twenty chapter regions" tabindex="0"></div><nav class="footer" aria-label="Map navigation"><button class="nav" data-nav="map" aria-label="Map"><img src="Assets/nav_map.png" alt="Карта"></button><button class="nav" data-nav="tasks" aria-label="Tasks"><img src="Assets/nav_tasks.png" alt="Задания"></button><button class="nav" data-nav="guild" aria-label="Guild"><img src="Assets/nav_guild.png" alt="Гильдия"></button></nav><div class="toast" id="toast" role="dialog" aria-modal="true"><span id="message"></span><br><button id="close">ПОНЯТНО</button></div></div></div><p class="note">The progress selector shows design examples only. The current game contains authored levels for Chapter 1. Later regions must remain unavailable in production until their content and unlock requirements exist.</p><p><a href="DesignReview.md">Design and implementation notes</a> · <a href="Sources/Chapters.json">Confirmed 20-chapter list</a> · <a href="Sources/OriginalReference.png">Original reference</a></p></main><script>
const chapters=CHAPTER_DATA,stage=document.getElementById('stage'),map=document.getElementById('map'),progress=document.getElementById('progress');let active=3,lastFocus;
function resize(){stage.style.transform=`scale(${document.getElementById('device').clientWidth/941})`}new ResizeObserver(resize).observe(document.getElementById('device'));resize();
function notice(text){lastFocus=document.activeElement;document.getElementById('message').textContent=text;document.getElementById('toast').classList.add('visible');document.getElementById('close').focus()}
function closeNotice(){document.getElementById('toast').classList.remove('visible');if(lastFocus)lastFocus.focus()}document.getElementById('close').onclick=closeNotice;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNotice()});
function render(){active=+progress.value;let old=map.scrollTop;map.innerHTML='';chapters.forEach(c=>{let state=c.id<active?'completed':c.id===active?'active':'locked';let status=state==='completed'?'Пройдено · можно вернуться':state==='active'?'Доступно · продолжить':'Закрыто';let el=document.createElement('button');el.className='region '+state;el.dataset.chapter=c.id;el.setAttribute('aria-label',`Глава ${c.id}. ${c.ru}. ${status}`);if(state==='locked')el.setAttribute('aria-disabled','true');el.innerHTML=`<img class="terrain" src="Assets/region_${String(c.id).padStart(2,'0')}.png" alt=""><span class="shade"></span><span class="number">${c.id}</span><span class="copy"><span class="chapter">ГЛАВА ${c.id}</span><strong class="name">${c.ru}</strong><span class="status">${status}</span></span>${state==='locked'?'<img class="lock" src="Assets/lock.png" alt="Закрыто">':state==='completed'?'<span class="check" aria-hidden="true">✓</span>':''}`;el.onclick=()=>notice(state==='locked'?`Глава ${c.id}: завершите предыдущую главу.`:`${c.ru} — ${state==='completed'?'повторное посещение':'переход к карте главы'}. Демонстрация дизайна.`);map.append(el)});map.scrollTop=old}
progress.onchange=render;document.getElementById('density').onchange=e=>stage.classList.toggle('compact',e.target.value==='4');document.getElementById('start').onclick=()=>map.scrollTo({top:0,behavior:'smooth'});document.getElementById('current').onclick=()=>{let el=map.querySelector(`[data-chapter="${Math.min(active,20)}"]`);map.scrollTo({top:Math.max(0,el.offsetTop-80),behavior:'smooth'})};document.querySelector('.back').onclick=()=>notice('Возврат на главный экран — демонстрация навигации.');document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{if(b.dataset.nav==='map')map.scrollTo({top:0,behavior:'smooth'});else notice(b.dataset.nav==='tasks'?'Задания главы — демонстрация навигации.':'Гильдия — демонстрация навигации.')});render();
</script></body></html>'''.replace('CHAPTER_DATA',data)
(b/'WorldMap_Regions_Design_R1_Review.html').write_text(html)
